handler_exact:
{(event) =>
                  handle(
                    event,
                    (data) => ({
                      action: "invitation",
                      email: data.get("email"),
                      role: data.get("role"),
                      canManageStock: data.get("role") === "admin",
                      canCountStock: false,
                    }),
                    "Convite criado. Compartilhe o link exibido abaixo.",
                  )
                }

{() =>
                          void execute(
                            {
                              action: "resendInvitation",
                              invitationId: row.id,
                            },
                            "Novo link de convite gerado.",
                          )
                        }

{() =>
                          void execute(
                            {
                              action: "revokeInvitation",
                              invitationId: row.id,
                            },
                            "Convite revogado.",
                          )
                        }

{() => {
                  try {
                    const parsed: unknown = JSON.parse(importText);
                    if (!Array.isArray(parsed))
                      throw new Error("O lote precisa ser uma lista.");
                    void execute(
                      {
                        action: "historicalImport",
                        preview: true,
                        rows: parsed,
                      },
                      "Pré-validação concluída.",
                    ).then((result) => setImportReviewed(Boolean(result)));
                  } catch (reason) {
                    setError(
                      reason instanceof Error
                        ? reason.message
                        : "JSON inválido.",
                    );
                  }
                }}

{() => {
                  try {
                    void execute(
                      {
                        action: "historicalImport",
                        rows: JSON.parse(importText),
                        preview: false,
                      },
                      "Importação processada. Revise o relatório por registro.",
                    );
                  } catch {
                    setError("Lote JSON inválido.");
                  }
                }}

{(event) =>
          handle(event, (data) => ({
            action: "alertRule",
            productId: data.get("productId"),
            location: data.get("location"),
            lowThreshold: String(data.get("lowThreshold")),
            criticalThreshold: String(data.get("criticalThreshold")),
            isEnabled: data.has("isEnabled"),
          }))
        }

{(event) =>
          handle(
            event,
            (data) => ({
              action: "recipient",
              id: creating ? null : (patient?.id ?? null),
              displayName: data.get("displayName"),
              isActive: data.has("isActive"),
              isDevelopment: globalMode
                ? data.has("isDevelopment")
                : patient?.is_development === true,
              ...((creating || !patient?.id) && globalMode
                ? {
                    initialAdministratorEmail: data.get(
                      "initialAdministratorEmail",
                    ),
                  }
                : {}),
            }),
            "Paciente salvo.",
            true,
          )
        }

{(event) => {
                event.preventDefault();
                const f = new FormData(event.currentTarget);
                void configure("membership", {
                  userId: f.get("userId"),
                  role: f.get("role"),
                });
              }}

{async () => {
              setBusy(true);
              setError("");
              try {
                await api("/api/profile", { action: "prepareLink" });
                const client = createSupabaseBrowserClient();
                if (!client) throw new Error("Auth indisponível.");
                const { error } = await client.auth.linkIdentity({
                  provider: "google",
                  options: {
                    redirectTo:
                      window.location.origin + "/auth/callback?next=/perfil",
                  },
                });
                if (error)
                  throw new Error(
                    "Habilite Google e vinculação manual no Supabase Auth para concluir esta operação.",
                  );
              } catch (reason) {
                setError(
                  reason instanceof Error
                    ? reason.message
                    : "Não foi possível vincular.",
                );
              } finally {
                setBusy(false);
              }
            }}

{(event) => {
              event.preventDefault();
              const form = new FormData(event.currentTarget);
              void save("/api/units", {
                careRecipientId:
                  form.get("scope") === "global"
                    ? null
                    : (context.patient?.id ?? null),
                code: form.get("code"),
                name: form.get("name"),
                dimension: form.get("dimension"),
                decimals: Number(form.get("decimals")),
              });
            }}

{(event) => {
                event.preventDefault();
                const form = new FormData(event.currentTarget);
                void save("/api/catalog/presentations", {
                  careRecipientId: context.patient!.id,
                  productId: product.id,
                  unit: form.get("unit"),
                  decimals: Number(form.get("decimals")),
                  ...(form.get("barcode")
                    ? {
                        barcode: form.get("barcode"),
                        name: form.get("name"),
                        baseQuantity: form.get("baseQuantity"),
                      }
                    : {}),
                });
              }}

{(event) => {
                              setLinks((current) => ({
                                ...current,
                                [option.productId]: event.target.checked
                                  ? [
                                      ...(current[option.productId] ?? []),
                                      request.lineId,
                                    ]
                                  : (current[option.productId] ?? []).filter(
                                      (id) => id !== request.lineId,
                                    ),
                              }));
                              if (event.target.checked)
                                setForm((current) => ({
                                  ...current,
                                  quantities: {
                                    ...current.quantities,
                                    [option.productId]:
                                      current.quantities[option.productId] ??
                                      "",
                                  },
                                }));
                            }}

{(event) =>
                            setForm((current) => {
                              const quantities = {
                                ...current.quantities,
                              };
                              if (event.target.checked)
                                quantities[product.id] = "";
                              else delete quantities[product.id];
                              return { ...current, quantities };
                            })
                          }

{() => {
                      setOpen(false);
                      void api("/api/notifications", { id: row.id }).then(
                        () =>
                          setRows((current) =>
                            current.map((item) =>
                              item.id === row.id
                                ? {
                                    ...item,
                                    seen_at: new Date().toISOString(),
                                  }
                                : item,
                            ),
                          ),
                        () =>
                          setError(
                            "Não foi possível marcar a notificação como lida.",
                          ),
                      );
                    }}

{async () => {
                    try {
                      await api("/api/notifications", { id: row.id });
                      setAttempt((value) => value + 1);
                    } catch (reason) {
                      setError(
                        reason instanceof Error
                          ? reason.message
                          : "Não foi possível marcar.",
                      );
                    }
                  }}

{async () => {
                setBusy(true);
                try {
                  await api("/api/profile", { action: "signoutOthers" });
                  setMessage(
                    "Outras sessões encerradas. Tokens já emitidos expiram conforme a configuração de Auth.",
                  );
                  setAttempt((value) => value + 1);
                } catch (reason) {
                  setError(
                    reason instanceof Error
                      ? reason.message
                      : "Não foi possível confirmar.",
                  );
                } finally {
                  setBusy(false);
                }
              }}

{() => {
                  if (line) removeLine(item.id);
                  else if (info?.pending.length) {
                    setDuplicate(item);
                    setRepeatReason("");
                  } else updateLine(item, {});
                }}

{(event) =>
                  setItems(
                    items.map((current) =>
                      current.id === item.id
                        ? { ...current, name: event.target.value }
                        : current,
                    ),
                  )
                }

{(event) =>
                  setItems(
                    items.map((current) =>
                      current.id === item.id
                        ? {
                            ...current,
                            currentStock: Number(event.target.value),
                          }
                        : current,
                    ),
                  )
                }

{(event) =>
                  setItems(
                    items.map((current) =>
                      current.id === item.id
                        ? { ...current, urgent: event.target.checked }
                        : current,
                    ),
                  )
                }

{(event) => {
              event.preventDefault();
              const form = new FormData(event.currentTarget);
              void send({
                action: "report",
                careRecipientId: context.patient!.id,
                kind: form.get("kind"),
                location: form.get("location"),
                text: form.get("text"),
                lines: Object.entries(lines).map(([productId, quantity]) => ({
                  productId,
                  quantity,
                })),
                idempotencyKey: crypto.randomUUID(),
              });
            }}

{(event) =>
                            setLines((current) => {
                              const next = { ...current };
                              if (event.target.checked) next[product.id] = "";
                              else delete next[product.id];
                              return next;
                            })
                          }

{() =>
                  void save({
                    id: row.id,
                    accept: false,
                    kind: "shortage",
                    text: "Sugestão descartada pelo próprio autor",
                    lines: [],
                  })
                }

{(event) => {
              event.preventDefault();
              const form = new FormData(event.currentTarget);
              setFilters({
                productId: String(form.get("productId")),
                from: String(form.get("from")),
                to: String(form.get("to")),
              });
              setPage(1);
              setLoading(true);
            }}
